name: Notify Dev Channel

on:
  push:
    branches:
      - master
    paths:
      - 'src/**'

jobs:
  notify:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout code
        uses: actions/checkout@v4
        with:
          fetch-depth: 2

      - name: Extract PR number from commit message
        id: extract_pr
        run: |
          COMMIT_MESSAGE=$(git log --format=%B -n 1)
          echo "commit_message=$COMMIT_MESSAGE" >> $GITHUB_ENV

          # Extract PR number using regex
          if [[ $COMMIT_MESSAGE =~ Merge\ pull\ request\ #([0-9]+) ]]; then
            PR_NUMBER="${BASH_REMATCH[1]}"
            echo "pr_number=$PR_NUMBER" >> $GITHUB_ENV
          fi

      - name: Get PR details
        if: env.pr_number != ''
        id: get_pr
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = process.env.PR_NUMBER;
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: parseInt(prNumber)
            });

            // Extract issue numbers from PR body
            const issueRegex = /(?:Closes|Fixes|Resolves)\s+#(\d+)/gi;
            let match;
            const issues = [];
            while ((match = issueRegex.exec(pr.body)) !== null) {
              issues.push(match[1]);
            }

            // Add PR number to issues array
            issues.push(prNumber);

            core.setOutput('pr_number', prNumber);
            core.setOutput('pr_title', pr.title);
            core.setOutput('pr_body', pr.body);
            core.setOutput('issues', JSON.stringify(issues));
            core.setOutput('author', pr.user.login);

      - name: Post comment to PR
        if: env.pr_number != '' && steps.get_pr.outputs.pr_number != ''
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = process.env.PR_NUMBER;
            const prTitle = process.env.PR_TITLE;
            const author = process.env.AUTHOR;

            const comment = `## 🧪 Your changes are now in the dev channel!

Your PR has been merged to master and is available for testing in the **dev channel**.

**Test your changes before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: \`uvx ha-mcp-dev\`

Docker commands:
\`\`\`bash
docker run -it --rm ghcr.io/homeassistant-ai/ha-mcp:dev
\`\`\`

Thank you for your contribution, @${author}! Please test these changes before the next stable release.`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: parseInt(prNumber),
              body: comment
            });

      - name: Post comment to linked issues
        if: env.pr_number != '' && steps.get_pr.outputs.issues != ''
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const issues = JSON.parse(process.env.ISSUES);
            const prNumber = process.env.PR_NUMBER;
            const prTitle = process.env.PR_TITLE;
            const author = process.env.AUTHOR;

            for (const issue of issues) {
              if (issue === prNumber) continue; // Skip the PR itself

              const comment = `## ✅ This issue has been addressed in the dev channel!

A fix for this issue has been merged to master (PR #${prNumber}) and is available for testing in the **dev channel**.

**Test the fix before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: \`uvx ha-mcp-dev\`

Docker commands:
\`\`\`bash
docker run -it --rm ghcr.io/homeassistant-ai/ha-mcp:dev
\`\`\`

Thank you for reporting this issue, @${author}! Please confirm the fix works before the next stable release.`;

              try {
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: parseInt(issue),
                  body: comment
                });
              } catch (error) {
                console.log(`Failed to comment on issue ${issue}:`, error.message);
              }
            }
